head.script:
scwin.gVar = {
    "cRef" : "",
    "cRefSync" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > P > refSync]<br/>입력값이 바인딩 된 DataCollection 에 반영되는 시점을 설정합니다.",
    "validation" : [
        "ref 속성이 설정되어 있지 않으면 해당 속성은 무시됩니다.",
        "true 설정 시, 입력창에서 키가 다운될 때 입력값을 DataCollection 에 반영합니다.",
        "true 설정 시, 다운된 키를 제외한 입력값이 DataCollectoin 에 반영됩니다.",
        "false 설정 시, Enter, Tab 키 입력 시, 포커스 아웃 시 입력값을 DataCollection 에 반영합니다.",
        "미설정 시, Enter, Tab 키 입력 시, 포커스 아웃 시 입력값을 DataCollection 에 반영합니다.",
        "refSync=true 일때 컴포넌트의 입력값이 DataCollection 에 반영되는 시점은 키가 다운되었을때 입니다.",
        "그러나, 키가 다운되었을때 컴포넌트의 입력값은 내부적으로 갱신되기 전 상태이므로 다운된 키가 DataCollection 에 반영되지 않습니다.",
        "따라서, 입력값이 모두 반영되는 시점에 주의하여야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출 (gdm_ref, gdl_boolean)
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정 (con_ref 는 라벨이 ref 문자열이라 인덱스로 선택 / gdl_boolean 은 코드값 1=미설정 2=true 3=false)
    con_ref.setSelectedIndex(1);
    con_refSync.setValue("1");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof label2 !== 'undefined') {
        label2.remove();
    }

    if (typeof mirror1 !== 'undefined') {
        mirror1.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트이며 con_ref, con_refSync 에서 선택한 값이 속성으로 적용됩니다\n바인딩 대상은 dataMap 인 gdm_ref.key1 이며 Target 재생성 시 빈값으로 초기화됩니다\n아래 바인딩 데이터 값 은 gdm_ref.key1 에 고정 바인딩된 표시 전용 textbox 라 con_ref 미설정일 때도 값이 변하는지 포커스를 유지한 채 볼 수 있습니다\n[절차] 위 조건 선택 -> Target 재생성 -> target1 에 abc 를 한 글자씩 타이핑하면서 바인딩 데이터 값 표시 변화를 관찰\n - 이어서 Enter -> 다시 타이핑 -> Tab -> 다시 타이핑 -> 값 확인 버튼 클릭 순으로 세 가지 반영 경로를 각각 확인\n[확인] password 라 화면으로 값을 읽을 수 없으므로 바인딩 데이터 값 표시와 결과창의 값 및 길이로 판정"', '', 'label1');

    // 조건 설정
    scwin.gVar["cRef"] = con_ref.getText();
    scwin.gVar["cRefSync"] = con_refSync.getText();

    // 바인딩 데이터 초기화 (입력 반영을 빈값에서부터 관찰)
    gdm_ref.set("key1", "");

    let properties = {
        ref : scwin.gVar["cRef"],
        refSync : scwin.gVar["cRefSync"],
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onkeydown", "onkeyup", "onblur"]);

    // comp 생성 함수 호출 (헬퍼가 생성 직후 setValue 로 초기값 secret 설정)
    await $c.gcm.createBasicSecret(cList, eList);

    // 헬퍼가 넣은 초기값을 지워 refSync 반영 결과만 남긴다
    target1.setValue("");
    gdm_ref.set("key1", "");

    // 바인딩 데이터 값을 실시간으로 표시 (con_ref 와 무관하게 gdm_ref.key1 고정 바인딩)
    $c.gcm.createLabel('label="바인딩 데이터 값 : "', '', 'label2');

    let strMirror = '<w2:textbox ' + $c.gcm.strNameSpace + ' id="mirror1" ref="data:gdm_ref.key1" class="tc_tbx_label_1" style="margin:5px;"></w2:textbox>';
    scwin.mirror1 = await $p.dynamicCreate("mirror1", "textbox", strMirror, $c.gcm.getTestGroup(''));
}



// 미설정 표기 변환
scwin.fn_disp = function (strValue) {
    return (strValue === "") ? "미설정" : strValue;
}



// 눌린 키 표기
scwin.fn_key = function (e) {
    if (!e)
        return "";

    return e.key || e.keyCode;
}



// 입력창 값과 바인딩 된 DataCollection 값 (password 라 값과 길이를 병기)
scwin.fn_state = function () {
    let strValue = target1.getValue() || "";
    let strBound = gdm_ref.get("key1") || "";

    return "target1 값 : " + strValue + " (" + strValue.length + "자) / 바인딩 데이터 값 : " + strBound + " (" + strBound.length + "자)";
}



// 키다운 시점의 반영값 - validation 2, 3, 6, 7 판정 출력
scwin.target1_onkeydown = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("onkeydown [" + scwin.fn_key(e) + "] -> " + scwin.fn_state());
}



// 키업 시점의 반영값 (키다운 시점과 대비) - validation 3, 7 판정 출력
scwin.target1_onkeyup = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("onkeyup [" + scwin.fn_key(e) + "] -> " + scwin.fn_state());
}



// 포커스 아웃 시점의 반영값 - validation 4, 5 판정 출력
scwin.target1_onblur = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("onblur -> " + scwin.fn_state());
}



// 조건별 최종 반영 결과 - validation 1, 4, 5, 8 판정 출력
scwin.btn_getValue_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("ref " + scwin.fn_disp(scwin.gVar["cRef"]) + " / refSync " + scwin.fn_disp(scwin.gVar["cRefSync"]) + " -> " + scwin.fn_state());
}
